"""Evaluate layered configuration requests against a policy."""

import re

_INTEGER = re.compile(r"^[+-]?\d+$")

def _failure(reason):
    return {"ok": False, "config": {}, "error": reason}

def _exact_type(value, expected):
    if expected == "boolean":
        return type(value) is bool
    if expected == "integer":
        return type(value) is int
    if expected == "string":
        return type(value) is str
    return False

def _parse_environment(value, expected):
    if type(value) is not str:
        return False, None
    if expected == "boolean":
        if value == "true":
            return True, True
        if value == "false":
            return True, False
        return False, None
    if expected == "integer":
        if _INTEGER.fullmatch(value) is None:
            return False, None
        return True, int(value, 10)
    if expected == "string":
        return True, value
    return False, None

def evaluate(request, policy):
    defaults = policy.get("defaults", {})
    types = policy.get("types", {})
    known = set(defaults)
    config = dict(defaults)

    for layer in request.get("layers", []):
        for key, value in layer.items():
            if key not in known:
                return _failure("unknown_key")
            if value is None and policy.get("null_resets") is True:
                config[key] = defaults[key]
            else:
                config[key] = value

    environment = request.get("environment")
    if environment is None and "env" in request:
        environment = request["env"]
    if environment is not None:
        if policy.get("environment") is not True:
            return _failure("environment")
        for key, value in environment.items():
            if key not in known:
                return _failure("unknown_key")
            valid, parsed = _parse_environment(value, types.get(key))
            if not valid:
                return _failure("environment")
            config[key] = parsed

    for key, expected in types.items():
        if key not in config or not _exact_type(config[key], expected):
            return _failure("type")

    return {"ok": True, "config": config, "error": None}

